import{_ as l,l as o,o as e,c as i,v as t,p as n,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"seL4 形式验证","description":"","frontmatter":{"title":"seL4 形式验证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/formal-verification-sel4.md","filePath":"cs/formal-verification-sel4.md","lastUpdated":1789023840000}'),p={name:"cs/formal-verification-sel4.md"};function E(f,a,_,m,u,B){const s=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="sel4-形式验证" tabindex="-1">seL4 形式验证 <a class="header-anchor" href="#sel4-形式验证" aria-label="Permalink to &quot;seL4 形式验证&quot;">​</a></h1><div class="epigraph"><p>seL4 把微内核的功能正确与完整性不变量做到机器可检查的证明：C 实现细化到抽象规格。它示范 TCB 小到可证，不示范「所有软件都应 Coq 一遍」。</p><footer>—— Klein et al., seL4: Formal Verification of an OS Kernel, SOSP 2009；后续完整性与时间隔离论文点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/sdl-lifecycle">SDL</a>是过程。安全进阶最后一课用 <strong>seL4</strong> 把 TCB 最小化接到<a href="/cs/proof-assistants">证明助手</a>的核：规格、细化、不变式。不重写 L4 IPC。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通内核太大不能证。seL4：抽象规格 ↔ Haskell 原型 ↔ C，证明细化与无用户到内核的完整性破坏（在模型内）。缺口是：证明排除的假设（硬件、汇编、编译器）仍要另管。</p><h3 id="不是万能内核" tabindex="-1">不是万能内核 <a class="header-anchor" href="#不是万能内核" aria-label="Permalink to &quot;不是万能内核&quot;">​</a></h3><p>设备驱动与用户态仍要隔离策略。证明的是核，不是整个产品。</p><p><span class="marginnote">Klein et al. SOSP 2009。对照本课程开头 Shannon：一端是信息论极限，一端是可证微内核。中间是合同与误用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述细化链。指出时间隔离后续工作。课程封口：后课若有附录不插入主干。</p>',12)),(e(),n(c,null,{default:r(()=>[h(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E6%8A%BD%E8%B1%A1%E8%A7%84%E6%A0%BC%22%5D%20--%3E%20REF%5B%22%E7%BB%86%E5%8C%96%E8%AF%81%E6%98%8E%22%5D%0A%20%20REF%20--%3E%20C%5B%22C%20%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20ASSUME%5B%22%E7%A1%AC%E4%BB%B6%E4%B8%8E%E7%BC%96%E8%AF%91%E5%99%A8%E5%81%87%E8%AE%BE%22%5D%20--%3E%20LIM%5B%22%E8%AF%81%E6%98%8E%E8%BE%B9%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>形式方法服务最小 TCB。安全进阶从一次一密走到可证内核：保密极限、计算合同、协议绑定、内存完整、观测响应、隐私预算、组织过程，最后证明核。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 seL4 当所有系统的必换内核。安全进阶课程到此结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SDL 是过程；seL4 是可证的最小核实例。</li><li>细化把规格接到 C；假设外仍要工程。</li><li>与开篇 Shannon 对照：极限、合同、可证 TCB。</li><li>安全进阶封口；证明助手课的核在此落地。</li><li>出处：Klein et al., SOSP 2009；对照 Shannon, 1949；<a href="/cs/proof-assistants">proof-assistants</a>。</li></ul>',8))])}const C=l(p,[["render",E]]);export{A as __pageData,C as default};
